  'A third-semester music theory course focused on chromatic harmony and form. Students analyze and write secondary dominants, modulations, mode mixture, Neapolitan and augmented-sixth chords, chromatic voice leading, binary and ternary forms, sonata form, rondo form, extended tertian harmony, and enharmonic reinterpretation while connecting these techniques to listening, keyboard realization, repertoire, performance, and creative application.',
  $mt3json${"slug": "music-theory-iii", "title": "Music Theory III", "description": "A third-semester music theory course focused on chromatic harmony and form. Students analyze and write secondary dominants, modulations, mode mixture, Neapolitan and augmented-sixth chords, chromatic voice leading, binary and ternary forms, sonata form, rondo form, extended tertian harmony, and enharmonic reinterpretation while connecting these techniques to listening, keyboard realization, repertoire, performance, and creative application.", "topics": [{"id": "cde13788-11c4-4da2-a031-7b94c98b6593", "type": "topic", "title": "Secondary Dominants", "description": "Secondary dominants expand tonal color by temporarily intensifying chords other than tonic.", "children": [{"id": "846646a5-65a2-4cc3-aca7-205d3e9049b8", "type": "subtopic", "title": "Tonicization", "children": [{"id": "f9db03d6-8ebf-4416-a2a2-5d0100ab0ddb", "type": "concept", "title": "local tonic"}, {"id": "64e5f7d6-dadb-409a-b1d1-996e4ea72dd5", "type": "concept", "title": "applied dominant"}, {"id": "94079026-aa17-454f-9430-8db30e15aa74", "type": "concept", "title": "temporary leading tone"}], "description": "Students learn how a chord can briefly sound like a local tonic without a full key change."}, {"id": "a52c9563-cd89-4b8e-8390-1bc8b2a3e28c", "type": "subtopic", "title": "Applied V and vii chords", "children": [{"id": "4763bd93-61b5-43de-9de5-9c2fee4d69b2", "type": "concept", "title": "V/V"}, {"id": "61825e26-b621-49d9-ab39-f43724f8dec1", "type": "concept", "title": "V/ii"}, {"id": "f14928ff-97b8-455c-80c7-26c4ed2caafd", "type": "concept", "title": "vii diminished/V"}], "description": "The class analyzes and writes common applied dominant and leading-tone sonorities."}, {"id": "aa44bc6c-1967-426e-8452-b256686fe665", "type": "subtopic", "title": "Resolution and voice leading", "children": [{"id": "67d5a206-de22-48c5-acc1-919411a4ca26", "type": "concept", "title": "raised leading tones"}, {"id": "d6d6d326-c52c-413d-94ea-b4fe4d3ec6ac", "type": "concept", "title": "seventh resolution"}, {"id": "e785649c-4888-4a7a-afb3-8180d4194a59", "type": "concept", "title": "common-tone retention"}], "description": "Students practice resolving chromatic tendency tones clearly."}]}, {"id": "37c1a344-de46-4991-b605-2c2a3041248e", "type": "topic", "title": "Modulation", "description": "Modulation teaches students how music moves between keys and how composers organize large tonal journeys.", "children": [{"id": "0d98e42d-3388-426d-9b71-16ea027ce226", "type": "subtopic", "title": "Pivot-chord modulation", "children": [{"id": "eecc13d0-971c-4d4d-9c66-5699b39e9944", "type": "concept", "title": "common chord"}, {"id": "74b6c80a-28b4-4ea9-a909-2e093834229a", "type": "concept", "title": "dual Roman numerals"}, {"id": "cdb5becd-5b45-48ba-bc1a-89d28c2f1046", "type": "concept", "title": "arrival cadence"}], "description": "Students identify and write modulations through chords shared by two keys."}, {"id": "6abee5c8-1c4a-41e4-9682-18156c99c8f8", "type": "subtopic", "title": "Direct and phrase modulation", "children": [{"id": "74fda217-6e9f-45ee-9eeb-5fd4751675d6", "type": "concept", "title": "direct modulation"}, {"id": "25fdd627-554e-4cdd-b301-9f3306c284c2", "type": "concept", "title": "phrase modulation"}, {"id": "17485fe1-e07e-4fdd-a52c-ecd24fdcf7d8", "type": "concept", "title": "sequence-driven modulation"}], "description": "The unit covers abrupt or phrase-boundary key changes common in many repertoires."}, {"id": "006b7a78-8d1d-40a6-ad2a-5f46be96a3ce", "type": "subtopic", "title": "Closely related keys", "children": [{"id": "c14f9e9f-ef17-42e2-8580-c69f2592099f", "type": "concept", "title": "dominant key"}, {"id": "f54e1f36-8542-4c46-9abf-2f292dd791b9", "type": "concept", "title": "relative major/minor"}, {"id": "577bee38-6e38-4d9d-a105-31e08a38f9f4", "type": "concept", "title": "subdominant area"}], "description": "Students learn likely tonal destinations and how they support form."}]}, {"id": "a4f52b1d-716a-42f2-b38c-41563d989d03", "type": "topic", "title": "Borrowed Chords and Mode Mixture", "description": "Mode mixture introduces expressive chromatic color by borrowing from parallel modes.", "children": [{"id": "bf6dc1b5-2cf1-43ed-a992-5675f09ce168", "type": "subtopic", "title": "Parallel major/minor borrowing", "children": [{"id": "03583933-69d2-4b8f-84a6-132f1044b49d", "type": "concept", "title": "iv in major"}, {"id": "9fa452da-894b-461a-a4d4-ed7429c883a3", "type": "concept", "title": "flat VI"}, {"id": "f293b880-50f2-4553-8f0b-5abf44109d5f", "type": "concept", "title": "flat VII"}], "description": "Students learn how chords from the parallel mode alter a passage's affect and function."}, {"id": "07972495-dccd-4cff-9685-ddd2f6bc8feb", "type": "subtopic", "title": "Mixture in melodies and cadences", "children": [{"id": "419e24ed-7010-4c80-b1a8-c90920ee812b", "type": "concept", "title": "lowered 6"}, {"id": "345dfe28-b1ce-4913-9582-d3d17ee0585d", "type": "concept", "title": "lowered 3"}, {"id": "b723988e-c4c2-4bb6-8f1e-2f4a332c6cb8", "type": "concept", "title": "minor plagal cadence"}], "description": "The class studies melodic lowered scale degrees and cadence color."}, {"id": "8d027f8d-164d-4637-b7f7-a9c94f77dfb9", "type": "subtopic", "title": "Expressive and stylistic use", "children": [{"id": "062a8fb7-3331-4bef-b868-8033bece4370", "type": "concept", "title": "coloristic borrowing"}, {"id": "f514c688-daad-4879-8acf-ff63004bbc85", "type": "concept", "title": "modal shading"}, {"id": "101d926f-60f2-4d12-9a63-cb1f0df44885", "type": "concept", "title": "dramatic emphasis"}], "description": "Students analyze mixture in classical, Romantic, popular, and media examples."}]}, {"id": "b3d37c31-e028-4d21-8cdb-170f8abe1d74", "type": "topic", "title": "Neapolitan and Augmented Sixth Chords", "description": "These chromatic predominant chords create powerful intensification before dominant arrival.", "children": [{"id": "530e61ad-5c00-4563-a731-642cc45948a9", "type": "subtopic", "title": "Neapolitan chord", "children": [{"id": "27ac8c56-d584-4ef1-b937-7f5be59ff292", "type": "concept", "title": "flat II"}, {"id": "54c76ef3-bfe4-405a-9a88-947634838da9", "type": "concept", "title": "N6"}, {"id": "49e29092-92b7-47c7-b403-e6deaed52be3", "type": "concept", "title": "predominant function"}], "description": "Students identify and write the lowered supertonic major chord, especially in first inversion."}, {"id": "5572b739-4ff9-4276-9b15-2a0f59fc0bed", "type": "subtopic", "title": "Augmented sixth types", "children": [{"id": "54b7e5ee-d21e-467b-8098-a0e3b670ab45", "type": "concept", "title": "It+6"}, {"id": "d8d6afdf-8ec5-4c05-8c00-b89d69a2bbbc", "type": "concept", "title": "Fr+6"}, {"id": "50f7491c-30d7-42fc-8da1-babfa24f5dbe", "type": "concept", "title": "Ger+6"}], "description": "The class compares Italian, French, and German augmented-sixth chords."}, {"id": "49f2d625-d015-4543-8722-e5f5db898505", "type": "subtopic", "title": "Voice-leading to dominant", "children": [{"id": "aab15bb3-75c9-4863-808a-f359c976b25d", "type": "concept", "title": "le-fi resolution"}, {"id": "e95775ae-3bf1-4e4d-ba9c-8c61867243b1", "type": "concept", "title": "dominant preparation"}, {"id": "ec20fda6-bdd8-4b0a-a310-591a21a3f08b", "type": "concept", "title": "parallel fifth avoidance"}], "description": "Students practice resolving characteristic chromatic intervals into V or cadential 6/4."}]}, {"id": "657c9a6b-0c5a-41af-86a8-2ec630a02a39", "type": "topic", "title": "Chromatic Voice Leading", "description": "Chromatic voice leading shows how small semitone motions can transform harmony and musical expression.", "children": [{"id": "ca354b72-c9e4-4918-83c5-94ab89b22f7b", "type": "subtopic", "title": "Chromatic passing and neighbor motion", "children": [{"id": "29a85794-f64c-4ebc-a11d-e3e3209ea260", "type": "concept", "title": "chromatic passing tone"}, {"id": "0952f6c4-38ac-4eb6-a807-44b8806075ca", "type": "concept", "title": "chromatic neighbor"}, {"id": "dde4bbb3-036a-4b1d-b82e-b1312d0f1a58", "type": "concept", "title": "linear embellishment"}], "description": "Students distinguish ornamental chromaticism from structural chromatic harmony."}, {"id": "cfd9bd90-1d87-4b3e-aaa2-e11d6cfe22fd", "type": "subtopic", "title": "Common-tone and contrary motion", "children": [{"id": "454503b8-beb5-4810-8b38-1756dce4b47c", "type": "concept", "title": "common-tone retention"}, {"id": "ecde1b5f-8652-4428-8c52-d21292ae5649", "type": "concept", "title": "contrary chromatic motion"}, {"id": "8ce47ece-2d6c-4938-b6f6-89765ca1e1f3", "type": "concept", "title": "voice exchange"}], "description": "The class studies efficient chromatic transformations between chords."}, {"id": "ec002ed7-9d1d-40de-820e-20dedc90f396", "type": "subtopic", "title": "Linear analysis", "children": [{"id": "92804653-c6bf-4f21-9063-df6336b6fa48", "type": "concept", "title": "bass-line chromaticism"}, {"id": "1bfe6021-9ff7-4ced-b5d5-31d67bb2b761", "type": "concept", "title": "inner-voice motion"}, {"id": "70ab90a5-8828-43bc-af04-0baf9ca03396", "type": "concept", "title": "outer-voice framework"}], "description": "Students learn to describe how voice-leading strands shape harmonic events."}]}, {"id": "8e0ae3bc-5f3b-4909-8e9c-df8ab46f2a1f", "type": "topic", "title": "Binary and Ternary Forms", "description": "This unit connects harmonic motion to formal design in smaller instrumental and vocal forms.", "children": [{"id": "75676e7e-1500-4176-b87a-4ad66fd07fff", "type": "subtopic", "title": "Binary form", "children": [{"id": "f2381641-ff55-4aa2-bc1c-c9bbd4ee7f13", "type": "concept", "title": "A/B design"}, {"id": "2017163d-6180-44c5-8357-bf3a2c566983", "type": "concept", "title": "rounded binary"}, {"id": "04d48eba-08db-4b17-b8c0-f1c261cb53e9", "type": "concept", "title": "repeat structure"}], "description": "Students analyze rounded and simple binary forms through cadence and key areas."}, {"id": "6359e727-e10a-4b47-9423-dd3783008006", "type": "subtopic", "title": "Ternary form", "children": [{"id": "536ed9b5-0adc-4753-8724-aeb81c6804d9", "type": "concept", "title": "ABA"}, {"id": "e50bbffc-8fe2-4b79-9fd6-a03005926d4f", "type": "concept", "title": "contrasting middle"}, {"id": "d554c5f2-a6ec-4bb8-8612-1b996daf3b75", "type": "concept", "title": "return transformation"}], "description": "The class studies return, contrast, and proportion in three-part designs."}, {"id": "a28d5470-a09c-420e-8e9c-0dbc8c4d4c46", "type": "subtopic", "title": "Form and harmony", "children": [{"id": "3d9639fb-4563-46eb-85cd-82b3bddb7f03", "type": "concept", "title": "sectional cadence"}, {"id": "929803b5-0261-4c7c-9924-b88c974aea92", "type": "concept", "title": "key plan"}, {"id": "15dcd482-dae1-4a6e-91a4-965db2e44f12", "type": "concept", "title": "thematic contrast"}], "description": "Students connect sectional design to modulation, cadence, and thematic return."}]}, {"id": "4525ec3f-446b-4dde-a15b-59f014a92aec", "type": "topic", "title": "Sonata Form", "description": "Sonata form gives students a sophisticated model for tonal drama, thematic contrast, development, and return.", "children": [{"id": "4179b426-2853-4a09-a489-4f01a9a79351", "type": "subtopic", "title": "Exposition", "children": [{"id": "6d12e9f9-0a8e-42f3-9b74-7291d454a8f8", "type": "concept", "title": "primary theme"}, {"id": "d8501b16-d099-461f-a93c-997356adaafd", "type": "concept", "title": "transition"}, {"id": "224ee190-c5c3-4448-92d8-439af4393870", "type": "concept", "title": "secondary theme"}], "description": "Students learn the roles of primary theme, transition, secondary theme, and closing material."}, {"id": "f0335880-1791-4fc0-96f0-2272409ae62d", "type": "subtopic", "title": "Development", "children": [{"id": "c9c55335-e9e2-400d-a17d-dde494b3d94e", "type": "concept", "title": "motivic development"}, {"id": "5bbc332a-43e0-4016-b3f0-3d0f557e53e7", "type": "concept", "title": "sequential modulation"}, {"id": "4881b39c-209b-4d04-99fa-fec53e95a479", "type": "concept", "title": "dominant preparation"}], "description": "The class studies fragmentation, sequencing, modulation, and harmonic instability."}, {"id": "8e5d3479-e009-4da3-a92d-a3365dc23c35", "type": "subtopic", "title": "Recapitulation and coda", "children": [{"id": "baff492a-58e0-4c99-9ca5-988ef39b3af1", "type": "concept", "title": "recapitulation"}, {"id": "47265af0-77b2-4c5e-86c8-2a12d30bc3b6", "type": "concept", "title": "tonal resolution"}, {"id": "22822fd1-e6ae-4fd5-a86a-2ddf56dad1b2", "type": "concept", "title": "coda function"}], "description": "Students analyze how return resolves tonal and thematic tensions."}]}, {"id": "51a5d96f-110b-4b92-b017-ddb927f2a7e2", "type": "topic", "title": "Rondo Form", "description": "Rondo form teaches students how recurring material interacts with contrasting episodes and tonal planning.", "children": [{"id": "ae5056fd-781a-4d79-990a-ff84fe22905b", "type": "subtopic", "title": "Refrain and episode design", "children": [{"id": "9a07b654-48e8-4fd8-82df-7ef929dabf67", "type": "concept", "title": "ABACA"}, {"id": "775b6efd-7549-484a-91a2-f9eed828e77c", "type": "concept", "title": "ABACABA"}, {"id": "d492703c-6c4d-416d-ab60-f27de7a806d7", "type": "concept", "title": "episode contrast"}], "description": "Students identify recurring themes and contrasting sections."}, {"id": "f0aa97c6-1897-4ea0-814c-495819eff606", "type": "subtopic", "title": "Tonal plan", "children": [{"id": "5e84b14a-b0a9-4bd7-aa69-819ec5d6441d", "type": "concept", "title": "refrain key"}, {"id": "3dfb398e-5232-43b2-b75d-f22f99782db8", "type": "concept", "title": "episode key"}, {"id": "90eb72d6-6643-48ce-94c9-b0cb316b15bc", "type": "concept", "title": "return strategy"}], "description": "The class studies how rondo episodes travel through related keys before return."}, {"id": "c40b7de1-3fd9-4037-8685-54ff3ae5a025", "type": "subtopic", "title": "Hybrid forms", "children": [{"id": "8f30754d-1c3b-480c-a450-cf88b184cce5", "type": "concept", "title": "sonata-rondo"}, {"id": "bf751069-9