set
  title = 'Music Theory III',
  goal = 'Music Theory III',
  summary = 'A third-semester music theory course focused on chromatic harmony and form. Students analyze and write secondary dominants, modulations, mode mixture, Neapolitan and augmented-sixth chords, chromatic voice leading, binary and ternary forms, sonata form, rondo form, extended tertian harmony, and enharmonic reinterpretation while connecting these techniques to listening, keyboard realization, repertoire, performance, and creative application.',
